const state={notice:null,boot:null,portrait:null,habits:null,summary:null,plan:null,prepared:null,context:'writing',view:'learn',busy:false,correcting:null,selectedSources:new Set(),comparisons:[],comparison:null,comparisonId:null,epoch:0,readEpoch:0,job:null,jobMessage:null,accuracyDraft:null};
const t = key => copy[language][key] || key;
const el = (tag, text, className) => {const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;};
const sourceId = () => 'workspace-review-'+crypto.randomUUID();
const localDate = value => {try{return new Date(value).toLocaleString(language==='zh'?'zh-CN':'en-US',{dateStyle:'medium',timeStyle:'short'});}catch(_){return value||'';}};
function notify(message,error=false,key=null,params={}){key=key||Object.keys(copy[language]).find(name=>copy[language][name]===message)||null;state.notice={message,error,key,params};renderNotice();$('notice').classList.toggle('error',error);$('notice').hidden=false;}
function notifyKey(key,params={}){notify('',false,key,params);}
function renderNotice(){if(!state.notice)return;const {message,key,params}=state.notice;$('notice').textContent=key?t(key).replace(/\{(\w+)\}/g,(_,name)=>params[name]??''):message;}
function empty(target,key){target.replaceChildren(el('div',t(key),'empty'));}
function actionButton(key,fn,cls='secondary'){const button=el('button',t(key),cls);button.type='button';button.addEventListener('click',()=>perform(fn));return button;}
function deleteButton(fn,hint='deleteHint'){let armed=false;const button=el('button',t('forget'),'quiet');button.title=t(hint);button.addEventListener('click',()=>{if(!armed){armed=true;button.textContent=t('confirmForget');return;}perform(fn);});return button;}
async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:{'X-Workspace-Token':token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok){const error=new Error(data.message||t('genericError'));error.code=data.code;throw error;}return data;}
const call=(name,args)=>api('/api/call',{name,arguments:args});
async function write(name,args,expectedRevision=state.boot.revision){const result=await call(name,{...args,expected_revision:expectedRevision});if(result.profile&&Number.isInteger(result.profile.revision)){if(result.profile.revision!==state.boot.revision){clearAnswers();invalidatePlan();}state.boot.revision=result.profile.revision;}return result;}
function clearCorrectionError(){const target=$('correction-error');target.textContent='';target.hidden=true;}
function reportError(message){
  if($('correct-dialog').open){const target=$('correction-error');target.textContent=message;target.hidden=false;}
  else notify(message,true);
}
async function perform(fn){
  if(state.busy)return;
  state.busy=true;document.body.setAttribute('aria-busy','true');
  try{await fn();}
  catch(error){
    if(error.code==='STALE_REVISION'){
      await refresh();
      if($('correct-dialog').open)$('correct-form').querySelector('[type=submit]').disabled=true;
      reportError(t('stale')+($('correct-dialog').open?' '+t('cancel'):''));
    }else reportError(error.code==='INDEPENDENT_JUDGMENT_CONFLICT'?t('judgmentConflict'):error.code==='UNKNOWN_TOOL'?t('apiUnavailable'):error.message||t('genericError'));
  }finally{state.busy=false;document.body.removeAttribute('aria-busy');}
}
function showView(view){state.view=view;document.querySelectorAll('.view').forEach(node=>node.hidden=node.id!=='view-'+view);document.querySelectorAll('.nav-button').forEach(node=>{node.classList.toggle('active',node.dataset.view===view);node.setAttribute('aria-current',node.dataset.view===view?'page':'false');});}
function setLanguage(){renderNotice();document.documentElement.lang=language==='zh'?'zh-CN':'en';document.querySelectorAll('[data-i18n]').forEach(node=>node.textContent=t(node.dataset.i18n));document.querySelectorAll('[data-placeholder]').forEach(node=>node.placeholder=t(node.dataset.placeholder));$('language').textContent=language==='zh'?'English':'中文';render();}
function invalidatePlan(){state.plan=null;state.prepared=null;renderPlan();}
function clearAnswers(){state.readEpoch++;state.comparison=null;state.accuracyDraft=null;$('actual-result').replaceChildren();}
async function refresh(){
  const epoch=++state.epoch,context=state.context,selected=state.comparisonId;
  clearAnswers();
  const boot=await api('/api/bootstrap');
  if(epoch!==state.epoch||context!==state.context)return;
  const changed=state.boot&&state.boot.revision!==boot.revision;
  state.boot=boot;if(changed)invalidatePlan();
  const args={context};
  const [portrait,habits,summary,comparisons]=await Promise.all([call('profile_portrait',args),call('profile_habits',args),call('profile_outcome_summary',args),call('profile_comparison_list',args)]);
  if(epoch!==state.epoch||context!==state.context)return;
  state.context=portrait.context||context;$('context').value=state.context;
  state.portrait=portrait;state.habits=habits;state.summary=summary;
  state.comparisons=boot.paused?[]:comparisons.comparisons;
  const allowed=new Set(boot.sources.filter(row=>row.context===state.context).map(row=>row.key));
  state.selectedSources=new Set([...state.selectedSources].filter(key=>allowed.has(key)));
  state.comparisonId=state.comparisons.some(row=>row.comparison_id===selected)?selected:null;
  render();
  if(state.comparisonId)await loadComparison(state.comparisonId);
}

function render(){if(!state.boot)return;const boot=state.boot;$('version').textContent='v'+boot.version;$('subject').textContent=boot.subject_id;$('revision').textContent=t('revision')+' '+boot.revision;$('state-pill').textContent=t(boot.paused?'paused':'active');$('state-pill').className='pill '+(boot.paused?'paused':'active');$('pause').textContent=t(boot.paused?'resume':'pause');$('contexts').replaceChildren(...boot.contexts.map(value=>{const option=el('option');option.value=value;return option;}));$('source-count').textContent=boot.sources.filter(row=>row.context===state.context).length;$('habit-count').textContent=(state.habits?.candidates||[]).filter(c=>c.status==='ready_to_review').length;$('rule-count').textContent=(state.portrait?.confirmed_preferences||[]).length;$('import').disabled=boot.paused||!boot.conversation_import_enabled;$('demo').disabled=$('import').disabled;$('import-state').textContent=boot.paused?t('pausedMessage'):!boot.conversation_import_enabled?t('disabledImport'):'';renderSources();renderHabits();renderProposals();renderRules();renderOverrides();renderPlan();renderOutcomes();renderConditions($('task-conditions'));renderModelControls();renderComparisons();if($('correct-dialog').open)renderConditions($('correct-conditions'));}
function renderSources(){const rows=state.boot.sources.filter(row=>row.context===state.context),target=$('sources');target.replaceChildren();if(!rows.length)return empty(target,state.boot.paused?'pausedMessage':'noSources');for(const row of rows){const node=el('div',undefined,'source-row'),label=el('label',undefined,'check-row'),checkbox=el('input');checkbox.type='checkbox';checkbox.checked=state.selectedSources.has(row.key);checkbox.addEventListener('change',()=>{if(checkbox.checked)state.selectedSources.add(row.key);else state.selectedSources.delete(row.key);renderModelControls();});label.append(checkbox,el('span',row.excerpt));node.append(label,el('div',localDate(row.at)+' · '+row.key.slice(-8),'source-meta'));node.append(deleteButton(async()=>{clearAnswers();await write('profile_forget_messages',{source_keys:[row.key]});await refresh();notifyKey('forgotten');}));target.append(node);}}

function evidenceDetails(evidence){const details=el('details');details.append(el('summary',t('showEvidence')));for(const source of evidence||[]){details.append(el('blockquote',source.quote||source.excerpt||'','evidence-quote'));details.append(el('small',[source.at?localDate(source.at):'',source.source_key?.slice(-8)||''].filter(Boolean).join(' · ')));}return details;}
function renderHabits(){const target=$('habits'),candidates=state.habits?.candidates||[];target.replaceChildren();if(!candidates.length)return empty(target,state.boot.paused?'pausedMessage':'noHabits');for(const item of candidates){const card=el('article',undefined,'habit-card'),top=el('div',undefined,'habit-top');top.append(el('h3',dimensionNames[language][item.dimension]+': '+(valueNames[language][item.value]||item.value)),el('span',t(item.status),'pill '+(item.status==='ready_to_review'?'ready':'')));card.append(top,el('div',item.supporting_sessions+' '+t('supported')+' · '+item.opposing_sessions+' '+t('opposed'),'habit-score'));if(item.evidence?.length)card.append(el('blockquote',item.evidence[0].quote,'evidence-quote'));card.append(evidenceDetails(item.evidence));const actions=el('div',undefined,'card-actions');const accept=actionButton('accept',async()=>{await write('profile_habit_review',{candidate_id:item.candidate_id,context:state.context,decision:'accept',source_id:sourceId()});await refresh();notifyKey('reviewDone');},'primary');accept.disabled=item.status!=='ready_to_review'||state.boot.paused;const reject=actionButton('reject',async()=>{await write('profile_habit_review',{candidate_id:item.candidate_id,context:state.context,decision:'reject',source_id:sourceId()});await refresh();notifyKey('reviewDone');});reject.disabled=accept.disabled;actions.append(accept,reject);card.append(actions);target.append(card);}}
function renderProposals(){const target=$('proposals'),items=state.portrait?.pending_preferences||[];target.replaceChildren();target.append(el('p',t('keywordHint'),'subtle'));if(!items.length)return target.append(el('p',t('noProposals'),'empty'));for(const item of items){const card=el('article',undefined,'habit-card');card.append(el('h3',item.statement),el('small',item.extractor==='host_model_proposal'?t('semanticProposal'):t('literalProposal')),el('p',conditionsText(item.conditions),'subtle'));if(item.dimension)card.append(el('p',(dimensionNames[language][item.dimension]||item.dimension)+(item.value?': '+(valueNames[language][item.value]||item.value):''),'subtle'));let evidence=item.evidence;if(!evidence?.length)evidence=(item.source_keys||[]).map(key=>state.boot.sources.find(row=>row.key===key)).filter(Boolean);const details=evidenceDetails(evidence);details.open=true;card.append(details);const label=el('label',t('replacePreference')),picker=el('select'),first=el('option',t(item.approval_replacements?.['']?.length?'updatePreference':'addPreference'));picker.id='replace-'+item.id;label.htmlFor=picker.id;first.value='';picker.append(first);for(const rule of state.portrait.confirmed_preferences||[]){const option=el('option',rule.statement+' · '+conditionsText(rule.conditions));option.value=rule.id;picker.append(option);}card.append(label,picker);const preview=el('div');card.append(preview);const actions=el('div',undefined,'card-actions');for(const decision of ['accept','reject'])actions.append(actionButton(decision,async()=>{await write('profile_proposal_review',{proposal_id:item.id,decision,source_id:sourceId(),...(decision==='accept'&&picker.value?{replace_rule_id:picker.value}:{})});await refresh();notifyKey('reviewDone');},decision==='accept'?'primary':'secondary'));const showReplacement=()=>{const peers=item.approval_replacements?.[picker.value]||[];preview.replaceChildren();if(peers.length){preview.append(el('p',t('replacementPreview')));for(const peer of peers)preview.append(el('p',peer.id+' · '+peer.statement+' · '+peer.scope+' · '+conditionsText(peer.conditions)));}actions.children[0].textContent=t(peers.length?'approveUpdate':'accept');};picker.addEventListener('change',showReplacement);showReplacement();card.append(actions);target.append(card);}}

function renderRules(){
  const target=$('confirmed'),omit=$('omit-rules'),rules=state.portrait?.confirmed_preferences||[];
  const blocked=state.portrait?.blocked_preferences||[],blockedTarget=$('blocked-rules');
  const previously=new Set([...omit.querySelectorAll('input:checked')].map(node=>node.value));
  target.replaceChildren();omit.replaceChildren();blockedTarget.replaceChildren();
  $('blocked-preferences').hidden=!blocked.length;
  if(!rules.length){empty(target,state.boot.paused?'pausedMessage':'noRules');empty(omit,'noRules');}
  for(const [items,container,applied] of [[rules,target,true],[blocked,blockedTarget,false]]){
    for(const rule of items){
      const card=el('article',undefined,'rule-card');
      card.append(el('p',rule.statement),el('small',(rule.scope==='*'?t('allContexts'):rule.scope)+(rule.dimension?' · '+(dimensionNames[language][rule.dimension]||rule.dimension):'')));
      card.append(el('small',conditionsText(rule.conditions)));if(rule.expires_at)card.append(el('small',(new Date(rule.expires_at)<new Date()?t('expiredRule')+' · ':'')+localDate(rule.expires_at)));
      const actions=el('div',undefined,'card-actions');
      actions.append(actionButton('correct',()=>openCorrection(rule)),deleteButton(async()=>{await write('profile_forget',{rule_id:rule.id});await refresh();notifyKey('forgotten');}));
      card.append(actions);container.append(card);
      if(!applied)continue;
      const label=el('label',undefined,'check-row'),input=el('input');
      input.type='checkbox';input.value=rule.id;input.checked=previously.has(rule.id);input.addEventListener('change',invalidatePlan);
      label.append(input,el('span',rule.statement));omit.append(label);
    }
  }
}
function renderOverrides(){const target=$('overrides'),old=Object.fromEntries([...target.querySelectorAll('select')].map(node=>[node.name,node.value]));target.replaceChildren();for(const [name,values] of Object.entries(state.boot.dimensions)){const group=el('div'),label=el('label',dimensionNames[language][name]),select=el('select');select.id='override-'+name;select.name=name;label.htmlFor=select.id;const unchanged=el('option',t('followProfile'));unchanged.value='';select.append(unchanged);for(const value of values){const option=el('option',valueNames[language][value]||value);option.value=value;select.append(option);}select.value=old[name]||'';select.addEventListener('change',invalidatePlan);group.append(label,select);target.append(group);}}
function planArguments(){const task=$('task').value.trim();if(!task)throw new Error(t('validTask'));return{context:state.context,task,task_conditions:readConditions($('task-conditions')),task_overrides:Object.fromEntries([...$('overrides').querySelectorAll('select')].filter(node=>node.value).map(node=>[node.name,node.value])),omit_rule_ids:[...$('omit-rules').querySelectorAll('input:checked')].map(node=>node.value),max_preference_chars:4000};}
const reasonLabels={en:{independent_judgment_conflict:'This instruction conflicts with evidence-based judgment and is not sent to the host.',different_context:'Saved for a different context.',omitted_for_this_task:'You left this preference out for this task.',current_task_override:'The current request takes precedence.',context_preference_takes_priority:'A context-specific preference takes precedence.',preference_budget:'Outside the preference text budget.',confirmed_global_preference:'Confirmed for use across contexts.',confirmed_context_preference:'Confirmed for this working context.',personalization_paused:'Personalization is paused.',paused:'Personalization is paused.',expired:'This preference has expired.',context_mismatch:'Saved for a different context.',task_override:'This task asks for a different setting.',omitted:'You left this preference out.',explicitly_omitted:'You left this preference out.',context_specific:'Matches this working context.',global:'Available across contexts.',global_shadowed:'A context-specific preference takes precedence.',budget_exceeded:'Outside the preference budget.',selected:'Selected for this task.'},zh:{independent_judgment_conflict:'这条要求与基于证据的判断冲突，不会传给宿主。',different_context:'这条偏好属于其他工作场景。',omitted_for_this_task:'你选择本次不用这条偏好。',current_task_override:'优先采用本次任务的明确要求。',context_preference_takes_priority:'优先采用当前场景的具体偏好。',preference_budget:'超出了本次偏好内容预算。',confirmed_global_preference:'这条偏好已确认，可用于多个场景。',confirmed_context_preference:'这条偏好已确认，适用于当前场景。',personalization_paused:'个性化已暂停。',paused:'个性化已暂停。',expired:'这条偏好已经过期。',context_mismatch:'这条偏好属于其他场景。',task_override:'本次任务采用了不同设置。',omitted:'你选择这次不用它。',explicitly_omitted:'你选择这次不用它。',context_specific:'与当前工作场景匹配。',global:'适用于所有场景。',global_shadowed:'优先采用这个场景的具体偏好。',budget_exceeded:'超出了本次偏好内容预算。',selected:'本次任务采用这条偏好。'}};
Object.assign(reasonLabels.en,{conditions_not_matched:'This preference’s task conditions do not match, or a required condition is unspecified.',condition_mismatch:'Task conditions do not match.',missing_task_condition:'A required task condition is unspecified.',more_specific_conditions_take_priority:'A preference with more specific matching conditions takes precedence.',conflicting_equal_specificity:'Equally specific preferences conflict; neither value is chosen.'});
Object.assign(reasonLabels.zh,{conditions_not_matched:'任务条件不匹配，或所需条件尚未指定。',condition_mismatch:'任务条件不匹配。',missing_task_condition:'尚未指定所需的任务条件。',more_specific_conditions_take_priority:'优先采用条件更具体且匹配的偏好。',conflicting_equal_specificity:'同等具体的偏好互相冲突，暂不采用其中任何值。'});
function renderPlan(){const plan=state.plan;$('plan-empty').hidden=!!plan;$('plan-result').hidden=!plan;if(!plan)return;$('judgment-panel').hidden=!plan.judgment_policy;$('baseline-prompt').textContent=plan.baseline_prompt;$('personalized-prompt').textContent=plan.personalized_prompt;const target=$('plan-decisions');target.replaceChildren();for(const [list,kind] of [[plan.selected,'selected'],[plan.excluded,'excluded']])for(const rule of list||[]){const row=el('div',undefined,'decision-row'),body=el('div');row.append(el('span',t(kind),'pill '+(kind==='selected'?'ready':'')));body.append(el('p',rule.statement),el('small',reasonLabels[language][rule.reason]||rule.reason));row.append(body);target.append(row);}for(const [dimension,value] of Object.entries(plan.task_overrides||{})){const row=el('div',undefined,'decision-row'),body=el('div');row.append(el('span',t('taskOverride'),'pill'));body.append(el('p',dimensionNames[language][dimension]+': '+(valueNames[language][value]||value)),el('small',plan.explicit_task_overrides?.[dimension]?t('explicitOverride'):t('automaticOverride')));row.append(body);target.append(row);}if(!target.children.length)empty(target,'noChanges');$('plan-notes').replaceChildren(el('p',t('manualConflict')));$('prepare').disabled=state.boot.paused||state.prepared===plan.plan_id;$('prepare').textContent=t(state.prepared===plan.plan_id?'preparedLabel':'prepareButton');}
function renderOutcomes(){const plans=state.summary?.plans||[],picker=$('feedback-plan'),selected=state.prepared||picker.value;picker.replaceChildren();if(!plans.length){const option=el('option',t('noPlans'));option.value='';picker.append(option);}else for(const plan of plans){const option=el('option',localDate(plan.created_at)+' · '+plan.plan_id.slice(-8));option.value=plan.plan_id;picker.append(option);}if(plans.some(plan=>plan.plan_id===selected))picker.value=selected;document.querySelectorAll('[data-rating]').forEach(button=>button.disabled=!picker.value||state.boot.paused);const target=$('outcome-history');target.replaceChildren();if(!plans.length)return empty(target,'noRatings');for(const plan of plans){const row=el('div',undefined,'outcome-row'),body=el('div'),outcome=plan.outcome;body.append(el('strong',plan.plan_id.slice(-12)),el('p',localDate(plan.created_at)+' · '+Object.keys(plan.rule_versions||{}).length+' '+t('ruleStat')));if(outcome){body.append(el('p',t(outcome.rating==='not_sure'?'notSure':outcome.rating)+' · '+t(outcome.basis==='response_use'?'responseReported':'promptOnly')));}else body.append(el('p',t('unrated')));const del=deleteButton(async()=>{await write('profile_plan_forget',{plan_id:plan.plan_id});if(state.prepared===plan.plan_id)state.prepared=null;await refresh();notifyKey('forgotten');});del.title=t('forgetPlan');row.append(body,del);target.append(row);}}
function openCorrection(rule){state.correcting=rule;state.correctingRevision=state.boot.revision;$('correct-form').querySelector('[type=submit]').disabled=false;clearCorrectionError();$('correct-text').value=rule.statement;const typed=$('correct-typed');typed.replaceChildren();if(rule.dimension&&state.boot.dimensions[rule.dimension]){const label=el('label',dimensionNames[language][rule.dimension]||rule.dimension),select=el('select');select.id='correct-value';label.htmlFor=select.id;for(const value of state.boot.dimensions[rule.dimension]){const option=el('option',valueNames[language][value]||value);option.value=value;select.append(option);}select.value=rule.value;select.addEventListener('change',()=>{$('correct-text').value=state.boot.statements[rule.dimension][select.value];});typed.append(label,select);}renderConditions($('correct-conditions'),rule.conditions||{});$('correct-dialog').showModal();}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.view)));
$('language').addEventListener('click',()=>{language=language==='en'?'zh':'en';try{localStorage.setItem('karmen-workspace-language',language);}catch(_){}setLanguage();});
$('refresh').addEventListener('click',()=>perform(refresh));
$('pause').addEventListener('click',()=>perform(async()=>{state.epoch++;state.comparisonId=null;state.comparisons=[];clearAnswers();renderComparisons();await write('profile_pause',{paused:!state.boot.paused});await refresh();}));
$('change-context').addEventListener('click',()=>perform(async()=>{const context=$('context').value.trim();if(!context)throw new Error(t('validContext'));state.epoch++;state.comparisonId=null;state.comparisons=[];state.selectedSources.clear();clearAnswers();state.context=context;invalidatePlan();await refresh();}));
$('context').addEventListener('keydown',event=>{if(event.key==='Enter')$('change-context').click();});
$('conversation-file').addEventListener('change',()=>perform(async()=>{const file=$('conversation-file').files[0];if(!file)return;if(file.size>1000000)throw new Error(t('largeFile'));$('conversation-json').value=await file.text();$('import-state').textContent=file.name;}));
$('import').addEventListener('click',()=>perform(async()=>{if(!$('conversation-json').value.trim())throw new Error(t('chooseConversation'));const conversation=JSON.parse($('conversation-json').value);if(new TextEncoder().encode(JSON.stringify(conversation)).length>990000)throw new Error(t('largeFile'));await write('conversation_import',{conversation});state.context=conversation.context.trim().toLowerCase();$('context').value=state.context;$('conversation-json').value='';$('conversation-file').value='';await refresh();notifyKey('importDone');}));
$('demo').addEventListener('click',()=>perform(async()=>{const context='demo-writing',day=new Date().toISOString().slice(0,10),prefix='workspace-demo-'+language+'-'+day.replaceAll('-','');const anchor=new Date(day+'T00:00:00Z').getTime();let imported=false;for(let index=1;index<=3;index++){const conversation={session_id:prefix+'-'+index,context,messages:[{id:'feedback',role:'user',text:language==='zh'?'太长了，请简短一点。':'Too long. Please keep it brief.',at:new Date(anchor-index*86400000).toISOString()}]};const result=await write('conversation_import',{conversation});if(!result.replayed)imported=true;}state.context=context;$('context').value=context;$('task').value=t('demoTask');await refresh();notifyKey(imported?'demoDone':'demoExists');}));
