$('preview').addEventListener('click',()=>perform(async()=>{state.plan=await call('profile_plan',planArguments());state.prepared=null;renderPlan();}));
$('prepare').addEventListener('click',()=>perform(async()=>{if(!state.plan)throw new Error(t('validTask'));const reviewedRevision=state.plan.revision;const result=await write('profile_plan_prepare',planArguments(),reviewedRevision);const plan=result.plan||result;await refresh();state.plan=plan;state.prepared=plan.plan_id;renderPlan();renderOutcomes();notifyKey('savedPlan');}));
