$('correct-form').addEventListener('submit',event=>{event.preventDefault();perform(async()=>{clearCorrectionError();const old=state.correcting;const rule={id:old.id,statement:$('correct-text').value.trim(),scope:old.scope,kind:'correction',source_id:sourceId(),source_summary:language==='zh'?'用户在本地工作台明确保存了这次纠正。':'The user explicitly saved this correction in the local workspace.'};rule.conditions=readConditions($('correct-conditions'));if(old.dimension){rule.dimension=old.dimension;rule.value=$('correct-value')?$('correct-value').value:old.value;}if(old.expires_at)rule.expires_at=old.expires_at;await write('profile_correct',{rule},state.correctingRevision);$('correct-dialog').close();await refresh();notifyKey('corrected');});});
