function conditionsText(conditions){return Object.entries(conditions||{}).map(([key,value])=>(conditionNames[language][key]||key)+': '+(conditionLabels[language][value]||value)).join(' · ')||t('unconditioned');}
function readConditions(target){return Object.fromEntries([...target.querySelectorAll('select')].filter(node=>node.value).map(node=>[node.name,node.value]));}
function renderConditions(target,values){
  const previous=values||readConditions(target);target.replaceChildren();
  for(const [key,options] of Object.entries(state.boot.condition_values||{})){
    const label=el('label',conditionNames[language][key]||key),select=el('select'),group=el('div');
    select.id=target.id+'-'+key;select.name=key;label.htmlFor=select.id;
    const any=el('option',t('anyCondition'));any.value='';select.append(any);
    for(const value of options){const option=el('option',conditionLabels[language][value]||value);option.value=value;select.append(option);}
    select.value=previous[key]||'';select.addEventListener('change',invalidatePlan);group.append(label,select);target.append(group);
  }
}
function renderModelControls(){
  const boot=state.boot,count=state.selectedSources.size;
  $('model-config').textContent=boot.model_enabled?t('configuredModel')+': '+boot.configured_model:t('modelsOff');
  $('plan-model-config').textContent=$('model-config').textContent;
  $('selected-count').textContent=count+' '+t('selectedExcerpts');
  $('semantic-learn').disabled=boot.paused||!boot.model_enabled||!!state.job||count<1||count>20;
  $('compare').disabled=boot.paused||!boot.model_enabled||!!state.job;
  if(state.job)setJobMessage('jobRunning',boot.configured_model);else renderJobMessage();
}
function renderComparisons(){
  const picker=$('saved-comparisons');picker.replaceChildren();
  const first=el('option',t(state.comparisons.length?'readComparison':'noComparisons'));first.value='';picker.append(first);
  for(const row of state.comparisons){const option=el('option',localDate(row.created_at)+' · '+row.comparison_id.slice(-8)+' · '+t(row.revealed?'revealed':'blinded'));option.value=row.comparison_id;picker.append(option);}
  picker.value=state.comparisonId||'';picker.disabled=state.boot.paused||!state.comparisons.length;
  renderAnswers();
}
async function loadComparison(id){
  const epoch=state.epoch,readEpoch=++state.readEpoch,context=state.context;
  state.comparison=null;state.comparisonId=id;renderAnswers();
  if(!id||state.boot.paused)return;
  const result=await call('profile_comparison_read',{comparison_id:id});
  if(epoch!==state.epoch||readEpoch!==state.readEpoch||context!==state.context||state.boot.paused||state.comparisonId!==id)return;
  if(result.revision!==state.boot.revision){await refresh();return;}
  state.comparison=result;renderAnswers();
}
function renderAnswers(){
  const target=$('actual-result');target.replaceChildren();const record=state.comparison;
  if(!record||state.boot.paused){state.accuracyDraft=null;return;}
  if(state.accuracyDraft?.comparisonId!==record.comparison_id||state.accuracyDraft?.revision!==record.revision){
    state.accuracyDraft={comparisonId:record.comparison_id,revision:record.revision,a:record.feedback?.accuracy_a||'not_checked',b:record.feedback?.accuracy_b||'not_checked'};
  }
  const draft=state.accuracyDraft;
  target.append(el('p',t(record.revealed?'revealed':'blinded'),'comparison-status'),el('p',t('configuredModel')+': '+record.model+' · '+localDate(record.created_at),'subtle'),el('p',conditionsText(record.task_conditions),'subtle'));
  const grid=el('div',undefined,'comparison-grid');
  for(const side of ['a','b']){
    const panel=el('section',undefined,'panel response-panel'),heading=el('h3',t(side==='a'?'answerA':'answerB'));
    panel.append(heading);
    if(record.revealed)panel.append(el('p',t(record.mapping[side]==='baseline'?'baseline':'personalized'),'pill'));
    panel.append(el('pre',record.answers[side],'actual-answer'));
    const label=el('label',t('accuracy')+' · '+side.toUpperCase()),select=el('select');select.id='accuracy-'+side;label.htmlFor=select.id;
    for(const value of ['not_checked','reported_correct','reported_incorrect']){const option=el('option',t(value));option.value=value;select.append(option);}
    select.value=draft[side];
    select.addEventListener('change',()=>{if(state.accuracyDraft===draft&&state.comparison===record)draft[side]=select.value;});
    panel.append(label,select);grid.append(panel);
  }
  target.append(grid,el('p',t('accuracyNote'),'subtle'),el('h3',t('voteLabel')));
  const votes=el('div',undefined,'rating-actions');
  for(const [choice,key] of [['a','voteA'],['b','voteB'],['tie','tie'],['neither','neither']])votes.append(actionButton(key,async()=>{
    const accuracy_a=$('accuracy-a').value,accuracy_b=$('accuracy-b').value;
    clearAnswers();await write('profile_comparison_vote',{comparison_id:record.comparison_id,source_id:sourceId(),choice,accuracy_a,accuracy_b});
    await refresh();notifyKey('voteRecorded');
  }));
  target.append(votes,el('p',t('voteNote'),'subtle'));
  if(record.feedback){const feedback=record.feedback;target.append(el('p',t('previousVote')+': '+t(({a:'voteA',b:'voteB',tie:'tie',neither:'neither'})[feedback.choice])+' · '+t(feedback.blinded?'blindedVote':'unblindedVote')+' · A: '+t(feedback.accuracy_a)+' · B: '+t(feedback.accuracy_b),'feedback-receipt'));}
  const actions=el('div',undefined,'task-actions');
  if(!record.revealed)actions.append(actionButton('reveal',async()=>{clearAnswers();await write('profile_comparison_reveal',{comparison_id:record.comparison_id});await refresh();}));
  actions.append(deleteButton(async()=>{clearAnswers();state.comparisonId=null;await write('profile_comparison_forget',{comparison_id:record.comparison_id});await refresh();notifyKey('forgotten');},'comparisonDeleteHint'));target.append(actions);
  if(record.revealed){const details=el('details');details.append(el('summary',t('selectedPreferences')));for(const rule of record.selected_preferences||[])details.append(el('p',rule.statement+' · '+conditionsText(rule.conditions)));target.append(details);const metadata=el('details');metadata.append(el('summary',t('executionDetails')),el('pre',JSON.stringify(record.execution_metadata,null,2)));target.append(metadata);}
}
async function startModelJob(kind){
  if(state.job)throw new Error(t('jobRunning'));
  const context=state.context;
  const args=kind==='learn'?{context,source_keys:[...state.selectedSources]}:planArguments();
  if(kind==='learn'&&(args.source_keys.length<1||args.source_keys.length>20))throw new Error(t('selectSources'));
  const result=await api('/api/model-jobs',{...args,kind,request_id:'workspace-'+crypto.randomUUID(),expected_revision:state.boot.revision});
  state.job={id:result.job_id,context,kind};renderModelControls();
  // Provider waiting does not own the global action lock: pause, refresh and context changes stay usable.
  void pollModelJob(state.job,result);
}
async function pollModelJob(job,result){
  if(state.job!==job)return;
  try{
    if(result.status==='running'){
      setTimeout(async()=>{if(state.job!==job)return;try{await pollModelJob(job,await api('/api/model-jobs/'+encodeURIComponent(job.id)));}catch(error){finishJobError(job,error);}},900);return;
    }
    state.job=null;renderModelControls();
    if(result.status==='failed'){finishJobError(job,result.error||{});return;}
    setJobMessage('jobCompleted');
    if(state.context!==job.context||state.boot.paused)return;
    await refresh();
    if(state.context!==job.context||state.boot.paused)return;
    if(job.kind==='compare'&&result.result?.comparison_id){const id=result.result.comparison_id;if(state.comparisons.some(row=>row.comparison_id===id)){state.comparisonId=id;$('saved-comparisons').value=id;await loadComparison(id);}}
    else if(job.kind==='learn')notifyKey(result.result?.abstained?'abstained':'learnResultCount',{count:result.result?.added_proposals??0});
  }catch(error){finishJobError(job,error);}
}
function renderJobMessage(){const status=state.jobMessage;const message=status?t(status.key)+(status.detail?' · '+status.detail:''):'';$('model-job-state').textContent=message;$('semantic-job-state').textContent=message;}
function setJobMessage(key,detail=''){state.jobMessage={key,detail};renderJobMessage();}
function finishJobError(job,error){if(state.job&&state.job!==job)return;state.job=null;renderModelControls();setJobMessage('jobFailed',error.code||'');notify(t('jobFailed')+': '+(error.message||t('genericError')),true);}
$('semantic-learn').addEventListener('click',()=>perform(()=>startModelJob('learn')));
$('compare').addEventListener('click',()=>perform(()=>startModelJob('compare')));
$('saved-comparisons').addEventListener('change',()=>perform(()=>loadComparison($('saved-comparisons').value)));

setLanguage();perform(refresh);
setInterval(async()=>{if(state.busy||!state.boot||document.hidden||$('correct-dialog').open)return;try{const boot=await api('/api/bootstrap');if(boot.revision!==state.boot.revision){await perform(refresh);notifyKey('profileChanged');}}catch(_){/* Explicit refresh exposes connection errors without interrupting form edits. */}},6000);

let forgetSessionArmed=false;
$('forget-session').addEventListener('input',()=>{forgetSessionArmed=false;$('forget-conversation').textContent=t('forgetSessionTitle');});
$('forget-conversation').addEventListener('click',()=>{if(!forgetSessionArmed){forgetSessionArmed=true;$('forget-conversation').textContent=t('confirmForget');return;}perform(async()=>{const session_id=$('forget-session').value.trim();if(!session_id)throw new Error(t('sessionRequired'));await write('profile_forget_conversation',{session_id});$('forget-session').value='';forgetSessionArmed=false;$('forget-conversation').textContent=t('forgetSessionTitle');await refresh();notifyKey('forgotten');});});
